import{_ as t,o as a,c as i,ao as r}from"./chunks/framework.D8MII8CY.js";const h=JSON.parse('{"title":"API reference","description":"","frontmatter":{},"headers":[],"relativePath":"api.md","filePath":"api.md","lastUpdated":null}'),o={name:"api.md"};function s(n,e,l,d,c,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="API-reference" tabindex="-1">API reference <a class="header-anchor" href="#API-reference" aria-label="Permalink to &quot;API reference {#API-reference}&quot;">​</a></h1><p>The API is grouped by the decisions users make. Start with the <a href="./api/simulation">simulation reference</a>, then use the page for the subsystem you are changing or composing.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Need</th><th style="text-align:right;">Reference</th></tr></thead><tbody><tr><td style="text-align:right;">construct a problem, run a solve, inspect results</td><td style="text-align:right;"><a href="./api/simulation">Simulation and results</a></td></tr><tr><td style="text-align:right;">set temperature or solubility</td><td style="text-align:right;"><a href="./api/conditions">Process conditions</a></td></tr><tr><td style="text-align:right;">choose or extend kinetic models</td><td style="text-align:right;"><a href="./api/kinetics">Kinetic models and rates</a></td></tr><tr><td style="text-align:right;">choose a solver or inspect quadrature</td><td style="text-align:right;"><a href="./api/solvers">Solvers and quadrature</a></td></tr><tr><td style="text-align:right;">load measurements or evaluate losses</td><td style="text-align:right;"><a href="./api/measurements">Measurements and losses</a></td></tr><tr><td style="text-align:right;">estimate parameters or propagate uncertainty</td><td style="text-align:right;"><a href="./api/inference">Inference and uncertainty</a></td></tr><tr><td style="text-align:right;">create plots or chain diagnostics</td><td style="text-align:right;"><a href="./api/plotting">Plotting and diagnostics</a></td></tr></tbody></table><h2 id="Parameter-layout" tabindex="-1">Parameter layout <a class="header-anchor" href="#Parameter-layout" aria-label="Permalink to &quot;Parameter layout {#Parameter-layout}&quot;">​</a></h2><p>For callers without an independent dissolution model, the compatibility layout is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[p_nucleation; p_growth; p_aggregation; p_breakage]</span></span></code></pre></div><p>For new code with independent dissolution, use:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[p_nucleation; p_growth; p_dissolution; p_aggregation; p_breakage]</span></span></code></pre></div><p>The structured top-level fields are <code>nucl</code>, <code>gr</code>, <code>diss</code>, <code>agg</code>, and <code>br</code> in the five-block form. The four-block overload omits <code>diss</code> entirely; it is not a zero-filled dissolution block.</p><h2 id="Cross-cutting-contracts" tabindex="-1">Cross-cutting contracts <a class="header-anchor" href="#Cross-cutting-contracts" aria-label="Permalink to &quot;Cross-cutting contracts {#Cross-cutting-contracts}&quot;">​</a></h2><ul><li><p>Public numerical units are SI: seconds, Kelvin, kg/m³, metres, and rates in m/s.</p></li><li><p><code>runsimulation</code> returns <code>(problem, solution)</code> and validates parameter-block lengths from the selected kinetic models.</p></li><li><p><code>Observable</code> is always a time series, even for one observation.</p></li><li><p><code>PE_Routine</code>, <code>run_abc</code>, and <code>MCMC_Routine</code> default to <code>outputdir = nothing</code>, so library calls do not write into the current directory implicitly.</p></li><li><p>ForwardDiff and finite-difference paths are the tested AD story. Reverse-mode Enzyme-through-ODE support is deferred.</p></li></ul><p>Custom nucleation families may subtype <code>CriSTool.AbstractFPNucleationFunction</code> by qualification/import; that base is not currently exported. The standard custom-rate signature is <code>(fn, parameters, problem, state, t)</code>.</p>',12)])])}const g=t(o,[["render",s]]);export{h as __pageData,g as default};
